<?php
use App\Application\Ranking\GestionarRanking;
use App\Application\Ranking\ConsultarRanking;
use App\Application\Operacion\ReglasOperativas;
use Illuminate\Support\Facades\Gate;
use Illuminate\Validation\ValidationException;
use Livewire\Component;
use Livewire\WithPagination;
use Livewire\Attributes\Locked;
use Mary\Traits\Toast;
new class extends Component {
 use WithPagination,Toast;
 public array $form=['activo'=>false,'privacidad'=>'codigo','agregacion'=>'media','inicio_semana'=>'jueves','motivo'=>'','bandas'=>[]];
 public array $calculation=['tipo'=>'diario','fecha'=>'','ruta_id'=>null,'motivo'=>''];
 #[Locked] public ?string $selected=null;
 public function boot(): void { Gate::authorize('administrar-ranking'); }
 public function mount(): void { $current=app(ReglasOperativas::class)->current('ranking'); if($current['version']>0) { $this->form=array_intersect_key($current['valores'],$this->form)+$this->form; } foreach(GestionarRanking::CAMPOS as $key=>$field) { $this->form['bandas'][$key]??=[['minimo'=>'','maximo'=>'','puntos'=>'']]; } $this->calculation['fecha']=today()->toDateString(); }
 public function addBand(string $key): void { Gate::authorize('administrar-ranking'); abort_unless(isset(GestionarRanking::CAMPOS[$key]),422); if(count($this->form['bandas'][$key])<100) { $this->form['bandas'][$key][]=['minimo'=>'','maximo'=>'','puntos'=>'']; } }
 public function removeBand(string $key,int $index): void { Gate::authorize('administrar-ranking'); abort_unless(isset(GestionarRanking::CAMPOS[$key]),422); unset($this->form['bandas'][$key][$index]); $this->form['bandas'][$key]=array_values($this->form['bandas'][$key]); }
 public function saveRules(): void { Gate::authorize('administrar-ranking'); $this->perform(function(): void { app(GestionarRanking::class)->configure(auth()->id(),$this->form); $this->success('Nueva versión de puntuación guardada.'); }); }
 public function calculate(): void { Gate::authorize('administrar-ranking'); $this->perform(function(): void { $run=app(GestionarRanking::class)->calculate(auth()->id(),$this->calculation); $this->selected=$run->uuid; $this->success('Cálculo guardado.'); }); }
 public function show(string $uuid): void { Gate::authorize('administrar-ranking'); app(ConsultarRanking::class)->detail(auth()->id(),$uuid); $this->selected=$uuid; }
 private function perform(Closure $op): void { $this->resetValidation(); try { $op(); } catch(ValidationException $e) { foreach($e->errors() as $key=>$messages) { $this->addError($key,$messages[0]); } } catch(\Illuminate\Auth\Access\AuthorizationException $e) { throw $e; } catch(Throwable $e) { report($e); $this->addError('operacion','No se pudo completar la operación. Puedes reintentar.'); } }
 public function with(): array { $q=app(ConsultarRanking::class); return ['records'=>$q->history(auth()->id()),'detail'=>$this->selected?$q->detail(auth()->id(),$this->selected):null,'rutas'=>$q->routes(),'fields'=>GestionarRanking::CAMPOS,'rule'=>app(ReglasOperativas::class)->current('ranking')]; }
}; ?>
