 @foreach($fields as $key=>$field)<div class="border border-base-300 rounded-lg p-4 space-y-3" wire:key="criterio-{{ $key }}"><h3 class="font-semibold">{{ $field[0] }} · {{ $field[1] }} · Peso {{ $field[3] }} %</h3><p>Dominio de captura 0–{{ $field[2] }}, no rango sanitario.</p>@foreach($form['bandas'][$key]??[] as $index=>$band)<div class="grid md:grid-cols-4 gap-3" wire:key="banda-{{ $key }}-{{ $index }}"><x-input label="Mínimo" type="number" step="0.0001" wire:model="form.bandas.{{ $key }}.{{ $index }}.minimo" /><x-input label="Máximo" type="number" step="0.0001" wire:model="form.bandas.{{ $key }}.{{ $index }}.maximo" /><x-input label="Puntos (0–100)" type="number" step="0.0001" wire:model="form.bandas.{{ $key }}.{{ $index }}.puntos" /><x-button label="Retirar banda" wire:click="removeBand('{{ $key }}',{{ $index }})" /></div>@endforeach<x-button label="Añadir banda" wire:click="addBand('{{ $key }}')" /></div>@endforeach
 <x-textarea label="Motivo y referencia de aprobación de criterios" wire:model="form.motivo" /><x-slot:actions><x-button label="Guardar versión de criterios" type="submit" spinner="saveRules" /></x-slot:actions></x-form></x-card>
